// Expression Trees cho phép bạn phân tích, sửa đổi và thực thi code một cách linh hoạt.
// Thường được sử dụng trong các thư viện ORM như Entity Framework để dịch truy vấn LINQ thành SQL.

using System;
using System.Linq.Expressions;

public class ExpressionTreeExample
{
    public void BuildAndRunExpression()
    {
        // Mục tiêu: Xây dựng một biểu thức tương đương với: (num > 5) && (num < 10)

        // 1. Tạo tham số đầu vào cho biểu thức (giống như 'num => ...')
        ParameterExpression numParam = Expression.Parameter(typeof(int), "num");

        // 2. Tạo các hằng số để so sánh
        ConstantExpression five = Expression.Constant(5, typeof(int));
        ConstantExpression ten = Expression.Constant(10, typeof(int));

        // 3. Tạo các biểu thức so sánh
        // num > 5
        BinaryExpression greaterThanFive = Expression.GreaterThan(numParam, five);
        // num < 10
        BinaryExpression lessThanTen = Expression.LessThan(numParam, ten);

        // 4. Kết hợp chúng lại bằng toán tử 'AND' (&&)
        BinaryExpression andExpression = Expression.AndAlso(greaterThanFive, lessThanTen);

        // 5. Tạo Lambda Expression từ biểu thức đã xây dựng
        // Đây là một object đại diện cho code, chưa phải là code có thể thực thi
        Expression<Func<int, bool>> lambda = Expression.Lambda<Func<int, bool>>(
            andExpression,
            new ParameterExpression[] { numParam }
        );

        Console.WriteLine("Cấu trúc biểu thức: " + lambda.ToString());

        // 6. Biên dịch (Compile) biểu thức thành một delegate có thể thực thi
        Func<int, bool> compiledLambda = lambda.Compile();

        // 7. Thực thi với các giá trị khác nhau
        bool resultFor7 = compiledLambda(7);   // True
        bool resultFor3 = compiledLambda(3);   // False
        bool resultFor12 = compiledLambda(12); // False

        Console.WriteLine("Kết quả với số 7: " + resultFor7);
        Console.WriteLine("Kết quả với số 3: " + resultFor3);
    }
}

/*
 * STACK (Ngăn xếp):
 * - Tốc độ truy cập rất nhanh.
 * - Kích thước cố định, được xác định khi chương trình bắt đầu.
 * - Dữ liệu được lưu và giải phóng theo cơ chế LIFO (Last-In, First-Out).
 * - Mỗi luồng (thread) có một Stack riêng.
 * - Lưu trữ các "Value Types" (kiểu giá trị): int, float, bool, double, struct, enum...
 * - Lưu trữ các con trỏ (pointers) trỏ đến các đối tượng trên Heap.
 */

public void StackExample()
{
    // Biến 'a' và 'b' là value types, được tạo trực tiếp trên Stack.
    int a = 10;
    int b = a; // Giá trị của 'a' được sao chép vào 'b'.

    b = 20; // Thay đổi 'b' không ảnh hưởng đến 'a'.
    // a vẫn là 10.
}

/*
 * HEAP (Đống):
 * - Tốc độ truy cập chậm hơn Stack.
 * - Vùng nhớ lớn, linh hoạt, được dùng để lưu trữ các đối tượng có kích thước động hoặc lớn.
 * - Dữ liệu không được giải phóng ngay lập tức mà phụ thuộc vào Garbage Collector (GC).
 * - Lưu trữ các "Reference Types" (kiểu tham chiếu): class, string, array, delegate...
 */

public class MyObject { public int Value; }

public void HeapExample()
{
    // 'obj1' là một tham chiếu (con trỏ) trên Stack,
    // trỏ đến một đối tượng MyObject được tạo trên Heap.
    MyObject obj1 = new MyObject { Value = 10 };

    // 'obj2' là một tham chiếu khác trên Stack.
    // Nó được gán để trỏ đến CÙNG một đối tượng trên Heap mà 'obj1' đang trỏ tới.
    MyObject obj2 = obj1;

    obj2.Value = 20; // Thay đổi giá trị của đối tượng qua 'obj2'.
    // Vì cả hai cùng trỏ đến một đối tượng, giá trị của obj1.Value bây giờ cũng là 20.
}

/*
 * KẾT LUẬN:
 * - Sử dụng 'struct' cho các kiểu dữ liệu nhỏ, đơn giản, bất biến để tận dụng tốc độ của Stack.
 * - Sử dụng 'class' cho các đối tượng phức tạp, có trạng thái, cần được truyền qua lại giữa các hàm
 *   mà không muốn sao chép toàn bộ dữ liệu.
 * - Cẩn thận khi truyền reference types vì thay đổi ở một nơi sẽ ảnh hưởng đến tất cả các tham chiếu khác.
 */

using System.Collections.Generic;

public class BoxingUnboxingExample
{
    public void DemonstrateBoxingAndUnboxing()
    {
        // --- Boxing ---
        // 'i' là một value type trên Stack.
        int i = 123;

        // Khi gán 'i' cho 'o' (là một object), quá trình Boxing xảy ra:
        // 1. Một đối tượng mới được cấp phát trên Heap.
        // 2. Giá trị của 'i' được sao chép vào đối tượng mới đó.
        // 'o' là một tham chiếu trên Stack trỏ đến đối tượng trên Heap này.
        object o = i; 

        // --- Unboxing ---
        // Khi gán ngược lại, quá trình Unboxing xảy ra:
        // 1. Kiểm tra kiểu dữ liệu của đối tượng mà 'o' trỏ tới có phải là 'int' không.
        // 2. Nếu đúng, sao chép giá trị từ đối tượng trên Heap vào biến 'j' trên Stack.
        int j = (int)o;

        // Cạm bẫy hiệu năng: Boxing trong vòng lặp hoặc với các Collection không generic (như ArrayList)
        // Tránh dùng ArrayList, hãy dùng List<T>

        // ArrayList yêu cầu mọi thứ phải là 'object', gây ra Boxing liên tục.
        // RẤT TỆ VỀ HIỆU NĂNG!
        System.Collections.ArrayList arrayList = new System.Collections.ArrayList();
        for (int k = 0; k < 1000; k++)
        {
            arrayList.Add(k); // Boxing xảy ra ở mỗi lần Add()
        }

        // Dùng List<int> là giải pháp đúng đắn.
        // Nó được thiết kế để làm việc trực tiếp với kiểu 'int', không có Boxing.
        // HIỆU NĂNG TỐT!
        List<int> genericList = new List<int>();
        for (int k = 0; k < 1000; k++)
        {
            genericList.Add(k);
        }
    }
}
